package com.cxy.workbench;
import org.json.*;
import java.util.*;

final class ActionPainter {
 static final String[] GROUPS={"优先做","正在做","当前可做","条件做","日常"};
 static final int[] COLORS={0xff73c7fa,0xff6ed9a6,0xffffe552,0xffff94a0,0xffc2abf5};
 static final class Hit {final float x,y,w,h;final String action,value;Hit(float a,float b,float c,float d,String e,String f){x=a;y=b;w=c;h=d;action=e;value=f;}}
 static List<JSONObject> items(JSONObject data,int group){List<JSONObject> result=new ArrayList<>();JSONArray array=data==null?null:data.optJSONArray(group==4?"calendarEvents":"items");if(array!=null)for(int n=0;n<array.length();n++){JSONObject item=array.optJSONObject(n);if(item!=null&&(group==4||Presentation.inGroup(item,GROUPS[group])))result.add(item);}return result;}
 static String project(JSONObject item){JSONArray a=item.optJSONArray("projects");String s=a==null?"":a.optString(0,"");return s.length()>=2?s.substring(s.length()-2):"·";}
 static String title(JSONObject item){return item.optString("label",item.optString("title","待命名事项"));}
 static int outerCount(int n){return n<=20?n:(int)Math.ceil(n*20.0/34);}
 static int owner(double x,double y,int n,float side){int outer=outerCount(n);double dx=x-side/2,dy=y-side/2,r=Math.hypot(dx,dy),angle=(Math.atan2(dy,dx)+Math.PI/2+2*Math.PI)%(2*Math.PI);for(int ring=0;ring<2;ring++){int count=ring==0?outer:n-outer;double boundary=side/2-ring*side/268*36;if(count>0&&r<=boundary&&r>=boundary-side/268*34){int index=Math.min(count-1,(int)(angle/(2*Math.PI)*count));return ring==0?index:outer+index;}}return -1;}
 static final Map<Integer,int[]> PALETTES=new HashMap<>();
 static synchronized int[] colors(int n){if(PALETTES.containsKey(n))return PALETTES.get(n);int[] result=new int[n];Arrays.fill(result,-1);int outer=outerCount(n);boolean[][] neighbors=new boolean[n][n];for(int a=0;a<n;a++)for(int b=0;b<n;b++){int ar=a<outer?0:1,br=b<outer?0:1,ac=ar==0?outer:n-outer,bc=br==0?outer:n-outer,ai=ar==0?a:a-outer,bi=br==0?b:b-outer;if(a==b)continue;if(ar==br)neighbors[a][b]=Math.abs(ai-bi)==1||Math.abs(ai-bi)==ac-1;else neighbors[a][b]=Math.min((ai+1.0)/ac,(bi+1.0)/bc)-Math.max((double)ai/ac,(double)bi/bc)>0.000001;}if(!color(result,neighbors,new int[5],n))throw new IllegalStateException("Ring palette cannot color layout");PALETTES.put(n,result);return result;}
 static boolean color(int[] assignment,boolean[][] edges,int[] uses,int remaining){if(remaining==0)return true;int selected=-1,bestSat=-1,bestDegree=-1;for(int i=0;i<assignment.length;i++)if(assignment[i]<0){Set<Integer> sat=new HashSet<>();int degree=0;for(int j=0;j<assignment.length;j++)if(edges[i][j]){degree++;if(assignment[j]>=0)sat.add(assignment[j]);}if(sat.size()>bestSat||sat.size()==bestSat&&degree>bestDegree){selected=i;bestSat=sat.size();bestDegree=degree;}}Integer[] candidates={0,1,2,3,4};Arrays.sort(candidates,(a,b)->Integer.compare(uses[a]*30+a,uses[b]*30+b));for(int c:candidates){boolean valid=true;for(int j=0;j<assignment.length;j++)if(edges[selected][j]&&assignment[j]==c)valid=false;if(valid){assignment[selected]=c;uses[c]++;if(color(assignment,edges,uses,remaining-1))return true;uses[c]--;assignment[selected]=-1;}}return false;}
 static List<Hit> draw(CardPainter.Surface p,JSONObject data,int group,String mode,int page,String selected,float h,boolean dark){
  CardPainter.Theme t=new CardPainter.Theme(dark);p.rect(0,0,360,h,22,t.bg);p.text("行动台",16,34,22,t.ink,true);p.rect(263,12,81,29,12,dark?0xff242932:0xffe9eaf0);p.rect(mode.equals("ring")?266:304,15,37,23,9,t.panel);CardPainter.icon(p,"ring",276,18,18,mode.equals("ring")?CardPainter.BLUE:t.muted);CardPainter.icon(p,"list",313,18,18,mode.equals("list")?CardPainter.BLUE:t.muted);
  List<Hit> hits=new ArrayList<>();hits.add(new Hit(12,8,130,36,"cycle",""));hits.add(new Hit(264,12,40,30,"mode","ring"));hits.add(new Hit(304,12,40,30,"mode","list"));
  for(int i=0;i<5;i++){float x=12+i*68;int count=items(data,i).size();if(i==group)p.rect(x,52,64,48,10,dark?0xff263b50:0xffe5eef9);int ink=i==group?i==4?0xff866dd0:0xff1577c8:t.muted;p.text(GROUPS[i],x+4,68,9,ink,i==group);p.text(data==null?"—":Integer.toString(count),x+4,89,16,ink,true);hits.add(new Hit(x,50,64,50,"group",Integer.toString(i)));}
  List<JSONObject> all=items(data,group);int capacity=group==4?Math.max(1,(int)((h-150)/53)):mode.equals("ring")?34:Math.max(2,(int)((h-144)/54));int pages=Math.max(1,(int)Math.ceil(all.size()/(double)capacity));page=Math.max(0,Math.min(page,pages-1));List<JSONObject> visible=all.subList(Math.min(all.size(),page*capacity),Math.min(all.size(),(page+1)*capacity));
  if(data==null){float side=Math.min(240,Math.max(150,h-180));p.arc(180,120+side/2,side/2-17,34,-90,360,t.faint);p.text("—",180-p.measure("—",38,true)/2,133+side/2,38,t.muted,true);p.text("连接后显示现有事项",180-p.measure("连接后显示现有事项",11,false)/2,120+side+28,11,t.muted,false);}
  else if(visible.isEmpty())p.text("暂无该分类事项",16,140,12,t.muted,false);
  else if(group==4){float y=122;for(JSONObject item:visible){p.text(item.optString("date","")+" "+item.optString("time",""),16,y,10,CardPainter.BLUE,true);p.text(CardPainter.trim(p,item.optString("title",""),315,12,true),16,y+19,12,t.ink,true);y+=53;}}
  else if(mode.equals("list")){float y=115;for(JSONObject item:visible){p.circle(20,y+8,3,COLORS[group%5]);p.text(CardPainter.trim(p,title(item),294,12,true),33,y+12,12,t.ink,true);String next=item.optString("next",item.optString("current",""));p.text(CardPainter.trim(p,next,294,10,false),33,y+30,10,t.muted,false);p.line(16,y+43,344,y+43,.6f,t.faint);hits.add(new Hit(12,y-5,336,48,"open",item.optString("id")));y+=54;}}
  else{
   float side=Math.min(268,Math.max(150,h-210)),left=(360-side)/2,top=112,scale=side/268;int n=visible.size(),outer=outerCount(n);int[] palette=colors(n);for(int i=0;i<n;i++){int ring=i<outer?0:1,index=ring==0?i:i-outer,count=ring==0?outer:n-outer;float radius=side/2-ring*36*scale-17*scale,step=360f/count,start=-90+index*step;p.arc(180,top+side/2,radius,34*scale,start,step,COLORS[palette[i]]);double angle=Math.toRadians(start+step/2);String label=project(visible.get(i));float fs=12*scale;p.text(label,(float)(180+radius*Math.cos(angle))-p.measure(label,fs,true)/2,(float)(top+side/2+radius*Math.sin(angle))+fs*.35f,fs,0xff18334d,true);}
   int total=data.optJSONArray("items")==null?0:data.optJSONArray("items").length();String number=Integer.toString(total);p.text(number,180-p.measure(number,38,true)/2,top+side/2+13,38,t.ink,true);hits.add(new Hit(145,top+side/2-35,70,70,"open",""));
   int cells=(int)Math.ceil(side/10),unitOwner;float unit=side/cells;for(int y=0;y<cells;y++){int x=0;while(x<cells){int from=x;unitOwner=owner((x+.5)*unit,(y+.5)*unit,n,side);x++;while(x<cells&&owner((x+.5)*unit,(y+.5)*unit,n,side)==unitOwner)x++;if(unitOwner>=0)hits.add(new Hit(left+from*unit,top+y*unit,(x-from)*unit,unit,"select",visible.get(unitOwner).optString("id")));}}
   float y=top+side+19;JSONObject chosen=null;for(JSONObject item:visible)if(item.optString("id").equals(selected))chosen=item;
   if(chosen!=null&&y+40<h-30){p.rect(16,y-3,328,Math.min(95,h-y-30),12,t.panel);p.text(CardPainter.trim(p,title(chosen),300,12,true),27,y+15,12,t.ink,true);p.text("下一步",27,y+31,8,t.muted,false);p.text(CardPainter.trim(p,chosen.optString("next",""),300,10,false),27,y+46,10,t.ink,false);}
   else for(int i=0;i<Math.min(5,visible.size())&&y+20<h-30;i++){JSONObject item=visible.get(i);p.text(project(item),16,y+9,10,CardPainter.BLUE,true);p.text(CardPainter.trim(p,title(item),280,11,false),46,y+9,11,t.ink,false);p.text("›",335,y+9,12,t.muted,false);hits.add(new Hit(12,y-4,336,23,"select",item.optString("id")));y+=25;}
  }
  String source="尚未同步";if(data!=null)try{source=java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss").withZone(java.time.ZoneId.of("Asia/Shanghai")).format(java.time.Instant.parse(data.optString("generatedAt","")));}catch(Exception ignored){source=data.optString("generatedAt","未知");}p.text(data==null?source:"同步 "+source,16,h-13,7,t.muted,false);p.text("↻",324,h-12,13,t.muted,false);hits.add(new Hit(309,h-32,35,32,"refresh",""));if(pages>1){p.text("‹",240,h-12,14,t.muted,false);p.text((page+1)+" / "+pages,259,h-13,8,t.muted,false);p.text("›",299,h-12,14,t.muted,false);hits.add(new Hit(225,h-32,30,32,"page",Integer.toString(Math.max(0,page-1))));hits.add(new Hit(285,h-32,25,32,"page",Integer.toString(Math.min(pages-1,page+1))));}
  return hits;
 }
}
